function parseCsv(text){
  const NL=String.fromCharCode(10);
  const CR=String.fromCharCode(13);
  const rows=[]; let row=[]; let cur=''; let q=false;
  const s=String(text||'').replace(/^\uFEFF/,'');
  for(let i=0;i<s.length;i++){
    const ch=s[i];
    if(q){
      if(ch==='"'){ if(s[i+1]==='"'){ cur+='"'; i++; } else q=false; }
      else cur+=ch;
    } else if(ch==='"'){ q=true; }
    else if(ch===','){ row.push(cur); cur=''; }
    else if(ch===NL||ch===CR){
      if(ch===CR&&s[i+1]===NL)i++;
      row.push(cur);
      if(row.some(c=>c!==''))rows.push(row);
      row=[]; cur='';
    } else cur+=ch;
  }
  if(cur!==''||row.length){ row.push(cur); if(row.some(c=>c!==''))rows.push(row); }
  if(!rows.length)return[];
  const headers=rows[0].map(h=>h.trim());
  return rows.slice(1).map(r=>{ const o={}; headers.forEach((h,idx)=>o[h]=r[idx]==null?'':r[idx]); return o; });
}
function coerce(table,row){
  const cols=SCHEMAS[table]||[]; const out={};
  for(const c of cols){
    let v=row[c.name]; if(v===undefined)v='';
    if(c.type==='boolean'){ const t=String(v).trim().toLowerCase(); out[c.name]=t==='true'||t==='1'||t==='yes'; }
    else if(c.type==='number'){ const n=Number(String(v).trim()); out[c.name]=String(v).trim()===''||Number.isNaN(n)?null:n; }
    else out[c.name]=v==null?'':String(v);
  }
  return out;
}
